const visual = {
  prepare: function (input) {
    return [
      { kind: 'text', payload: '7' },
      { kind: 'text', payload: '3' },
      { kind: 'text', payload: '7:3' }
    ];
  },
  render: function (input, metrics) {
    var ms = (metrics && metrics.length) ? metrics : [];
    var W = input.viewport.widthDu;
    var H = input.viewport.heightDu;
    var left = W * 0.12;
    var right = W * 0.88;
    var span = right - left;
    var y = H * 0.5;
    var split = left + span * 0.7;
    var tick = Math.max(8, Math.min(H * 0.07, 16));
    var labelY = y - tick - 12;
    var smallSize = 16;
    var ratioSize = 20;
    var leadBottom = y + tick * 1.4 + 14;

    var paths = [
      { id: 'seg', commands: visualSdk.polyline([[left, y], [right, y]]) },
      { id: 'tickL', commands: visualSdk.polyline([[left, y - tick], [left, y + tick]]) },
      { id: 'tickR', commands: visualSdk.polyline([[right, y - tick], [right, y + tick]]) },
      { id: 'tickS', commands: visualSdk.polyline([[split, y - tick * 1.4], [split, y + tick * 1.4]]) },
      { id: 'lead', commands: visualSdk.polyline([[split, y + tick * 1.4], [split, leadBottom]]) }
    ];

    return {
      schemaVersion: 1,
      sceneId: 'ratio-7-3',
      revision: input.revision,
      viewBox: { x: 0, y: 0, width: W, height: H },
      paths: paths,
      root: {
        type: 'group',
        children: [
          { type: 'path', pathId: 'seg', stroke: '#26354a', strokeWidth: 2 },
          { type: 'path', pathId: 'tickL', stroke: '#26354a', strokeWidth: 2 },
          { type: 'path', pathId: 'tickR', stroke: '#26354a', strokeWidth: 2 },
          { type: 'path', pathId: 'tickS', stroke: '#c2410c', strokeWidth: 2 },
          { type: 'path', pathId: 'lead', stroke: '#c2410c', strokeWidth: 1 },
          { type: 'label', x: (left + split) / 2, y: labelY, text: '7', fontSize: smallSize, anchor: 'middle', fill: '#26354a' },
          { type: 'label', x: (split + right) / 2, y: labelY, text: '3', fontSize: smallSize, anchor: 'middle', fill: '#26354a' },
          { type: 'label', x: split, y: leadBottom + ratioSize, text: '7:3', fontSize: ratioSize, anchor: 'middle', fill: '#c2410c' }
        ]
      }
    };
  }
};
